import React, { useEffect, useState } from 'react';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';

const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'];
const periods = [
  '1 (8:00–8:50)', '2 (8:50–9:40)', '3 (9:40–10:30)', '4 (10:30–11:20)',
  '5 (11:20–12:10)', '6 (12:10–1:00)', '7 (1:00–1:50)', '8 (1:50–2:40)',
  '9 (2:40–3:30)', '10 (3:30–4:20)', '11 (4:20–5:10)'
];

const FacultyTimetable = () => {
  const [teacherList, setTeacherList] = useState([]);
  const [selectedTeacher, setSelectedTeacher] = useState('');
  const [timetable, setTimetable] = useState({});
  const [loading, setLoading] = useState(false);

  const token = localStorage.getItem('accessToken');

  useEffect(() => {
    fetchTeachers();
  }, []);

  const fetchTeachers = () => {
    axios.get('http://localhost:8000/api/teachers/', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(response => setTeacherList(response.data))
      .catch(error => console.error('Error fetching teachers:', error));
  };

  const handleViewTimetable = () => {
    if (!selectedTeacher) return;

    setLoading(true);

    axios.get(`http://localhost:8000/api/timetable/?teacher_id=${selectedTeacher}`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(response => {
        console.log("API Response:", response);
        console.log("Timetable Data:", response.data);

        if (response.data && response.data.length > 0) {
          const formattedTimetable = {
            Monday: Array(11).fill(''),
            Tuesday: Array(11).fill(''),
            Wednesday: Array(11).fill(''),
            Thursday: Array(11).fill(''),
            Friday: Array(11).fill('')
          };

          response.data.forEach(entry => {
            const { day, time, subject, room, is_lab } = entry;
            const periodIndex = periods.indexOf(time);

            if (day && periodIndex !== -1) {
              const value = `${subject} (Room ${room})`;

              if (is_lab) {
                // Fill two periods for labs
                formattedTimetable[day][periodIndex] = value;
                if (periodIndex + 1 < periods.length) {
                  formattedTimetable[day][periodIndex + 1] = value;
                }
              } else {
                formattedTimetable[day][periodIndex] = value;
              }
            } else {
              console.warn(`Invalid day or period: ${day} ${time}`);
            }
          });

          console.log("Formatted Timetable:", formattedTimetable);
          setTimetable(formattedTimetable);
        } else {
          console.error("No timetable data received.");
        }

        setLoading(false);
      })
      .catch(error => {
        console.error('Error fetching timetable:', error);
        setLoading(false);
      });
  };

  return (
    <div className="container my-5">
      <h3 className="mb-4 text-danger">Teacher Timetable Viewer</h3>

      <div className="mb-4 d-flex align-items-center">
        <select
          className="form-select w-auto me-3"
          value={selectedTeacher}
          onChange={e => setSelectedTeacher(e.target.value)}
        >
          <option value="">Select Teacher</option>
          {teacherList.map(teacher => (
            <option key={teacher.id} value={teacher.id}>
              {teacher.first_name} {teacher.last_name}
            </option>
          ))}
        </select>

        <button className="btn btn-danger" onClick={handleViewTimetable}>
          View Timetable
        </button>
      </div>

      {loading && <p>Loading timetable...</p>}

      {!loading && Object.keys(timetable).length > 0 && (
        <div className="table-responsive">
          <table className="table table-bordered table-striped text-center align-middle">
            <thead className="table-danger">
              <tr>
                <th>Periods / Days</th>
                {periods.map((period, idx) => (
                  <th key={idx}>{period}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {days.map(day => (
                <tr key={day}>
                  <th>{day}</th>
                  {(timetable[day] || Array(11).fill('')).map((value, idx) => (
                    <td key={idx}>{value || 'No Class'}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default FacultyTimetable;
